const projects=[{id:'erp',title:'Modüler ERP',category:'İŞ SÜREÇLERİ',status:'Geliştiriliyor',summary:'Stok, muhasebe ve raporlama için modüler ERP.',tech:['C# / .NET','MSSQL','OOP'],description:'Stok, muhasebe ve raporlama süreçlerini modüler bir yapıda bir araya getirmek için geliştirdiğim ERP projesi.',features:['Stok ve envanter süreçlerini ortak bir yapıda ele alma','Muhasebe ve raporlama iş akışları','C#/.NET ve nesne yönelimli programlama ile modüler geliştirme'],note:'Geliştirme aşamasında. Karttaki ekran, projenin odağını anlatan temsili bir arayüzdür.',art:`<div class="ui-preview"><div class="ui-top"><i></i><i></i><i></i><span>ERP</span></div><div class="erp-body"><div class="ui-side"><i></i><i></i><i></i><i></i><i></i></div><div class="ui-main"><h4>Operasyona genel bakış</h4><div class="mini-stats"><div>ENVANTER<b>Stok</b></div><div>FİNANS<b>Muhasebe</b></div><div>ANALİZ<b>Raporlar</b></div></div><div class="bars">${[30,50,38,65,45,80,65,95].map(h=>`<i style="height:${h}%"></i>`).join('')}</div></div></div></div>`},{id:'ai',title:'Akıllı yaşam asistanı',category:'AI & OTOMASYON',status:'Tasarım / geliştirme',summary:'Ses ve cihaz kontrolü için geliştirdiğim ev asistanı.',tech:['Yapay zekâ','Arduino','NFC'],description:'Ses, kamera ve cihaz kontrolünü merkezi bir panel üzerinden birleştirmeyi hedefleyen kişisel yapay zekâ ve ev otomasyonu asistanı.',features:['Sesli etkileşim ve kamera özelliklerinin tasarımı','Cihaz kontrolü için merkezi bir yönetim paneli','NFC ve Arduino tabanlı ev otomasyonu'],note:'Tasarım ve geliştirme aşamasında. Görsel, hedeflenen deneyimin konsept gösterimidir.',art:`<div class="assistant-ui"><div class="wave">${[15,26,40,55,30,65,42,58,25,45,60,34,50,22,14].map((h,i)=>`<i style="height:${h}px;--i:${i}"></i>`).join('')}</div><p>Kişisel ev otomasyonu asistanı</p><div class="device-row"><span>SES</span><span>KAMERA</span><span>CİHAZLAR</span></div></div>`},{id:'cv',title:'AI CV Maker',category:'FULL STACK & AI',status:'Geliştirildi',summary:'Next.js ve FastAPI ile geliştirdiğim CV oluşturucu.',tech:['Next.js','FastAPI','PostgreSQL'],description:'Next.js arayüzünü, FastAPI servislerini ve PostgreSQL veritabanını bir araya getiren yapay zekâ destekli CV oluşturucu.',features:['Yapay zekâ destekli CV oluşturma deneyimi','Next.js ile web arayüzü','FastAPI ve PostgreSQL tabanlı API ve veri katmanı'],note:'Karttaki ekran temsili bir arayüzdür; canlı uygulama ekran görüntüsü değildir.',art:`<div class="cv-screen"><div class="cv-controls"><strong>CV Maker</strong><i></i><i></i><i></i><span>AI ile oluştur ↗</span></div><div class="cv-page"><b></b>${Array(16).fill('<i></i>').join('')}</div></div>`}];
projects.unshift({id:'os',title:'SNAKE OS',category:'SİSTEM GELİŞTİRME',status:'Geliştiriliyor',summary:'Sıfırdan geliştirdiğim mobil işletim sistemi.',tech:['İşletim sistemi','Mobil','Bağımsız proje'],description:'SNAKE OS, sıfırdan geliştirdiğim kişisel mobil işletim sistemi projem. Projeyi bağımsız olarak geliştiriyorum; çalışmalarım devam ediyor.',features:['Telefon için sıfırdan işletim sistemi geliştirme','Bağımsız yürütülen kişisel sistem projesi'],note:'Geliştirme aşamasında. Görsel kavramsal bir gösterimdir; çalışan sistemin ekran görüntüsü değildir.',art:`<div class="os-concept"><strong>SNAKE OS.</strong><span class="os-subtitle">SIFIRDAN BİR MOBİL İŞLETİM SİSTEMİ.</span><div class="os-layers"><span>SİSTEM</span><i></i><span>MOBİL</span><i></i><span>DENEYİM</span></div></div>`});
projects.push({id:'stock',title:'Depo stok programı',category:'DEPO & ENVANTER',status:'Geliştirildi',summary:'Depo ve stok süreçleri için geliştirdiğim uygulama.',tech:['C#','MSSQL'],description:'C# ve MSSQL kullanarak geliştirdiğim depo stok programı. Depo ve stok işlemleri için hazırladığım bu uygulamada verileri MSSQL üzerinde tuttum.',features:['Depo ve stok yönetimine odaklı uygulama','C# ile uygulama geliştirme','MSSQL veritabanı kullanımı'],note:'Karttaki ekran, proje konusunu anlatan temsili bir arayüzdür.',art:`<div class="stock-concept"><div class="stock-title">DEPO / STOK</div><div class="stock-head"><span>UYGULAMA KATMANI</span><b>C#</b></div><div class="stock-connect">↓</div><div class="stock-head"><span>VERİTABANI KATMANI</span><b>MSSQL</b></div></div>`});
document.querySelector('#project-grid').innerHTML=projects.map((p,i)=>`<button class="project-card" data-project="${p.id}" aria-haspopup="dialog" aria-label="${p.title} projesinin detaylarını aç"><div class="project-art ${p.id}-art"><span class="art-status">${p.status}</span><div aria-hidden="true">${p.art}</div></div><div class="project-meta"><h3>${p.title}</h3><span aria-hidden="true">↗</span></div><p>${p.summary}</p><div class="tags">${p.tech.map(t=>`<span>${t}</span>`).join('')}</div></button>`).join('');
const dialog=document.querySelector('#project-dialog');let opener;
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{opener=button;const p=projects.find(p=>p.id===button.dataset.project);document.querySelector('#dialog-content').innerHTML=`<span class="dialog-kicker">${p.category} · ${p.status}</span><h2 id="dialog-title">${p.title}</h2><p>${p.description}</p><h3>Proje hakkında</h3><ul>${p.features.map(f=>`<li>${f}</li>`).join('')}</ul><div class="tags">${p.tech.map(t=>`<span>${t}</span>`).join('')}</div><p class="detail-note">${p.note}</p><a class="button primary" href="mailto:yilanciserkan30@gmail.com?subject=${encodeURIComponent(p.title+' hakkında')}">Proje hakkında konuşalım ↗</a>`;dialog.setAttribute('aria-labelledby','dialog-title');dialog.showModal();document.body.style.overflow='hidden'}));
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{document.body.style.overflow='';opener?.focus()});
document.querySelector('#copy-email').addEventListener('click',async()=>{const status=document.querySelector('#copy-status');try{await navigator.clipboard.writeText('yilanciserkan30@gmail.com');status.textContent='E-posta adresi kopyalandı.'}catch{status.textContent='Kopyalanamadı. Adres: yilanciserkan30@gmail.com'}setTimeout(()=>status.textContent='',5000)});
document.querySelector('#year').textContent=new Date().getFullYear();
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.section-heading,.project-card,.about-grid,.capabilities article,.timeline article,.contact h2').forEach((e,i)=>{e.classList.add('reveal');observer.observe(e)})}
let ticking=false;const progress=document.querySelector('.scroll-progress');window.addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(()=>{const total=document.documentElement.scrollHeight-innerHeight;progress.style.width=`${total>0?scrollY/total*100:0}%`;ticking=false});ticking=true}},{passive:true});
